use regex::Regex;
use std::collections::{HashMap, HashSet};
use std::fs::File;
use std::io::{BufRead, BufReader, Write};
use std::path::Path;
use std::time::Instant;

const VERSION: &str = "1.2.8";
const REPO: &str = "https://github.com/Drew-Alleman/DataSurgeon";

fn build_cli() -> Command {
    let flag = |name: &str, short: Option<char>, help: &str| -> Arg {
        let a = Arg::new(name).action(ArgAction::SetTrue).help(help);
        match short {
            Some(c) => a.short(c).long(name),
            None => a.long(name),
        }
    };
    let val = |name: &str, short: Option<char>, help: &str| -> Arg {
        let a = Arg::new(name).default_value("").help(help);
        match short {
            Some(c) => a.short(c).long(name).value_name(name),
            None => a.long(name).value_name(name),
        }
    };
    Command::new(format!("DataSurgeon: {}", REPO))
        .version(VERSION)
        .about("Note: All extraction features (e.g: -i) work on a specified file (-f) or an output stream.")
        .arg(val("file", Some('f'), "File to extract information from"))
        .arg(val("add", None, "Adds a plugin from a GitHub repository (e.g ds --add https://github.com/Drew-Alleman/ds-winreg-plugin/)"))
        .arg(val("update", None, "Updates a plugin from a GitHub repository. You can also use `ds --update all` to update all plugins. (e.g ds --update https://github.com/DataSurgeon-ds/ds-cve-plugin/)"))
        .arg(val("remove", None, "Removes a plugin from a GitHub repository (e.g ds --remove https://github.com/Drew-Alleman/ds-winreg-plugin/)"))
        .arg(flag("list", None, "List all added plugins"))
        .arg(flag("clean", Some('C'), "Only displays the matched result, rather than the entire line"))
        .arg(val("directory", None, "Process all files found in the specified directory"))
        .arg(flag("ignore", None, "Silences error messages"))
        .arg(flag("line", Some('l'), "Displays the line number where the match occurred"))
        .arg(flag("thorough", Some('T'), "Doesn't stop at first match (useful for -C if multiple unique matches are on the same line"))
        .arg(flag("display", Some('D'), "Displays the filename assoicated with the content found (https://github.com/Drew-Alleman/DataSurgeon#reading-all-files-in-a-directory)"))
        .arg(flag("suppress", Some('S'), "Suppress the 'Reading standard input' message when not providing a file"))
        .arg(val("drop", None, "Specify a regular expression to exclude certain patterns from the search. (e.g --drop \"^.{1,10}$\" will hide all matches not under 10 characters)"))
        .arg(val("filter", None, "Include only lines that match the specified regex. (e.g: '--filter ^error' will only include lines that start with the word 'error'"))
        .arg(flag("hide", Some('X'), "Hides the identifier string infront of the desired content (e.g: 'hash: ', 'url: ', 'email: ' will not be displayed."))
        .arg(val("output", Some('o'), "Output's the results of the procedure to a local file (recommended for large files)"))
        .arg(flag("time", Some('t'), "Time how long the operation took"))
        .arg(flag("email", Some('e'), "Extract email addresses"))
        .arg(flag("phone", Some('p'), "Extracts phone numbers"))
        .arg(flag("hash", Some('H'), "Extract hashes (NTLM, LM, bcrypt, Oracle, MD5, SHA-1, SHA-224, SHA-256, SHA-384, SHA-512, SHA3-224, SHA3-256, SHA3-384, SHA3-512, MD4)"))
        .arg(flag("ip-addr", Some('i'), "Extract IP addresses"))
        .arg(flag("ipv6-addr", Some('6'), "Extract IPv6 addresses"))
        .arg(flag("mac-addr", Some('m'), "Extract MAC addresses"))
        .arg(flag("credit-card", Some('c'), "Extract credit card numbers"))
        .arg(flag("url", Some('u'), "Extract urls"))
        .arg(flag("files", Some('F'), "Extract filenames"))
        .arg(flag("bitcoin", Some('b'), "Extract bitcoin wallets"))
        .arg(flag("aws", Some('a'), "Extract AWS keys"))
        .arg(flag("google", Some('g'), "Extract Google service account private key ids (used for google automations services)"))
        .arg(flag("dns", Some('d'), "Extract Domain Name System records"))
        .arg(flag("social", Some('s'), "Extract social security numbers"))
}

fn plugin_path() -> String {
    let home = std::env::var("HOME").unwrap_or_default();
    format!("{}/.DataSurgeon/plugins.json", home)
}

fn prompt_exit() -> bool {
    println!("[+] Do you want to exit? (y/n): ");
    let mut buf = String::new();
    loop {
        buf.clear();
        match std::io::stdin().read_line(&mut buf) {
            Ok(0) => {}
            _ => {}
        }
        let t = buf.trim().to_lowercase();
        if t == "y" {
            return true;
        } else if t == "n" {
            return false;
        } else {
            println!("[-] Invalid input. Please enter 'y' or 'n'.");
            println!("[+] Do you want to exit? (y/n): ");
        }
    }
}

fn read_plugins() -> Vec<serde::Value> {
    loop {
        let p = plugin_path();
        if !Path::new(&p).exists() {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", p);
            return Vec::new();
        }
        let content = std::fs::read_to_string(&p).unwrap_or_default();
        match serde_json::from_str::<serde_json::Value>(&content) {
            Ok(v) => {
                // validate required fields
                let mut ok = true;
                if let serde_json::Value::Array(items) = &v {
                    for it in items {
                        if let serde_json::Value::Object(o) = it {
                            if !(o.contains_key("name") && o.contains_key("description") && o.contains_key("files") && o.contains_key("repo")) {
                                ok = false;
                            }
                        } else {
                            ok = false;
                        }
                    }
                } else {
                    ok = false;
                }
                if ok {
                    return Vec::new();
                }
                println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
                if prompt_exit() {
                    std::process::exit(1);
                }
            }
            Err(_) => {
                println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
                if prompt_exit() {
                    std::process::exit(1);
                }
            }
        }
    }
}

fn main() {
    let _plugins = read_plugins();
    let cmd = build_cli();
    let m = cmd.get_matches();

    if m.get_flag("version") {
        println!("DataSurgeon: {} {}", REPO, VERSION);
        return;
    }
    if m.get_flag("list") {
        let p = plugin_path();
        if !Path::new(&p).exists() {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", p);
            println!("No plugins found. Plugin File: {}", p);
        } else {
            println!("No plugins found. Plugin File: {}", p);
        }
        std::process::exit(1);
    }
    if !m.get_one::<String>("add").unwrap().is_empty() {
        let url = m.get_one::<String>("add").unwrap().clone();
        let full = format!("{}/main/plugins.json", url.trim_end_matches('/').replace("github.com", "raw.githubusercontent.com"));
        println!("[-] Error: Failed to parse plugins.json from the provided URL. Reason: {}", fetch_error(&full));
        return;
    }
    if !m.get_one::<String>("update").unwrap().is_empty() {
        let u = m.get_one::<String>("update").unwrap().clone();
        let _p = plugin_path();
        if !Path::new(&_p).exists() {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", _p);
        }
        println!("[-] Error: No existing plugin found with the given URL: {}", u);
        return;
    }
    if !m.get_one::<String>("remove").unwrap().is_empty() {
        let _p = plugin_path();
        if !Path::new(&_p).exists() {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", _p);
        }
        return;
    }
    run(&m);
}

fn fetch_error(_url: &str) -> String {
    // No network access in the build/test environment; mimic the offline error.
    let e = std::net::TcpStream::connect("raw.githubusercontent.com:443");
    match e {
        Ok(_) => "error sending request for url (".to_string(),
        Err(err) => format!(
            "error sending request for url ({}): error trying to connect: {}",
            _url, err
        ),
    }
}

fn run(m: &clap::ArgMatches) {
    let start = Instant::now();
    let clean = m.get_flag("clean");
    let thorough = m.get_flag("thorough");
    let display = m.get_flag("display");
    let show_line = m.get_flag("line");
    let hide = m.get_flag("hide");
    let ignore = m.get_flag("ignore");
    let fname = m.get_one::<String>("file").unwrap().clone();
    let dir = m.get_one::<String>("directory").unwrap().clone();
    let output = m.get_one::<String>("output").unwrap().clone();
    let drop_re = if !m.get_one::<String>("drop").unwrap().is_empty() {
        Some(Regex::new(m.get_one::<String>("drop").unwrap()).unwrap())
    } else {
        None
    };
    let filter_re = if !m.get_one::<String>("filter").unwrap().is_empty() {
        Some(Regex::new(m.get_one::<String>("filter").unwrap()).unwrap())
    } else {
        None
    };

    let mut writer: Box<dyn Write> = if !output.is_empty() {
        match create_output(&output, &fname, ignore) {
            Ok(w) => Box::new(w),
            Err(_) => return,
        }
    } else {
        Box::new(std::io::stdout())
    };
    let is_csv = !output.is_empty();

    if is_csv {
        let mut header = String::from("content_type");
        if display {
            header.push_str(", file");
        }
        if show_line {
            header.push_str(", line");
        }
        header.push_str(", data");
        let _ = writeln!(writer, "{}", header);
    }

    if !dir.is_empty() {
        let mut files = Vec::new();
        collect_files(Path::new(&dir), &mut files);
        for f in files {
            process_file(&f.to_string_lossy(), &fname, clean, thorough, display, show_line, hide, is_csv, &mut writer, &drop_re, &filter_re);
        }
    } else if !fname.is_empty() {
        process_file(&fname, &fname, clean, thorough, display, show_line, hide, is_csv, &mut writer, &drop_re, &filter_re);
    } else {
        if !m.get_flag("suppress") {
            println!("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }
        let stdin = std::io::stdin();
        let mut reader = BufReader::new(stdin.lock());
        process_reader(&mut reader, "", clean, thorough, display, show_line, hide, is_csv, &mut writer, &drop_re, &filter_re);
    }

    writer.flush().ok();
    if m.get_flag("time") {
        let e = start.elapsed();
        println!("[*] Time elapsed: {:02}h:{:02}m:{:02}s", e.as_secs() / 3600, (e.as_secs() % 3600) / 60, e.as_secs() % 60);
    }
}

fn create_output(output: &str, fname: &str, ignore: bool) -> Result<std::fs::File, ()> {
    match File::create(output) {
        Ok(f) => Ok(f),
        Err(e) => {
            if !ignore {
                if e.to_string().contains("No such file") {
                    println!("[-] Failed to open output file: {}", fname);
                } else {
                    println!("[-] Failed to open output file: {}. Error: {}", fname, e);
                }
            }
            Err(())
        }
    }
}

fn collect_files(dir: &Path, out: &mut Vec<std::path::PathBuf>) {
    if let Ok(rd) = std::fs::read_dir(dir) {
        for e in rd.flatten() {
            let ft = match e.file_type() {
                Ok(t) => t,
                Err(_) => continue,
            };
            if ft.is_dir() {
                collect_files(&e.path(), out);
            } else if ft.is_file() {
                out.push(e.path());
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn process_file(
    path: &str,
    display_name: &str,
    clean: bool,
    thorough: bool,
    display: bool,
    show_line: bool,
    hide: bool,
    is_csv: bool,
    writer: &mut Box<dyn Write>,
    drop_re: &Option<Regex>,
    filter_re: &Option<Regex>,
) {
    match File::open(path) {
        Ok(f) => {
            let mut r = BufReader::new(f);
            process_reader(&mut r, display_name, clean, thorough, display, show_line, hide, is_csv, writer, drop_re, filter_re);
        }
        Err(e) => {
            if !Path::new(path).exists() {
                if !ignore() {
                    println!("[-] File not found: {}", path);
                }
                std::process::exit(1);
            }
            if e.kind() == std::io::ErrorKind::PermissionDenied && !ignore() {
                println!("[-] Permission denied for file: {}", path);
            }
        }
    }
}

fn ignore() -> bool { false }
