fn plugin_path() -> String {
    let home = std::env::var("HOME").unwrap_or_default();
    format!("{}/.DataSurgeon/plugins.json", home)
}

fn prompt_exit() -> bool {
    println!("[+] Do you want to exit? (y/n): ");
    let mut buf = String::new();
    loop {
        buf.clear();
        match std::io::stdin().read_line(&mut buf) {
            Ok(0) => {}
            _ => {}
        }
        let t = buf.trim().to_lowercase();
        if t == "y" {
            return true;
        } else if t == "n" {
            return false;
        } else {
            println!("[-] Invalid input. Please enter 'y' or 'n'.");
            println!("[+] Do you want to exit? (y/n): ");
        }
    }
}

fn read_plugins() -> Vec<serde::Value> {
    loop {
        let p = plugin_path();
        if !Path::new(&p).exists() {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", p);
            return Vec::new();
        }
        let content = std::fs::read_to_string(&p).unwrap_or_default();
        match serde_json::from_str::<serde_json::Value>(&content) {
            Ok(v) => {
                // validate required fields
                let mut ok = true;
                if let serde_json::Value::Array(items) = &v {
                    for it in items {
                        if let serde_json::Value::Object(o) = it {
                            if !(o.contains_key("name") && o.contains_key("description") && o.contains_key("files") && o.contains_key("repo")) {
                                ok = false;
                            }
                        } else {
                            ok = false;
                        }
                    }
                } else {
                    ok = false;
                }
                if ok {
                    return Vec::new();
                }
                println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
                if prompt_exit() {
                    std::process::exit(1);
                }
            }
            Err(_) => {
                println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
                if prompt_exit() {
                    std::process::exit(1);
                }
            }
        }
    }
}

fn main() {
    let _plugins = read_plugins();
    let cmd = build_cli();
    let m = cmd.get_matches();

    if m.get_flag("version") {
        println!("DataSurgeon: {} {}", REPO, VERSION);
        return;
    }
    if m.get_flag("list") {
        let p = plugin_path();
        if !Path::new(&p).exists() {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", p);
            println!("No plugins found. Plugin File: {}", p);
        } else {
            println!("No plugins found. Plugin File: {}", p);
        }
        std::process::exit(1);
    }
    if !m.get_one::<String>("add").unwrap().is_empty() {
        let url = m.get_one::<String>("add").unwrap().clone();
        let full = format!("{}/main/plugins.json", url.trim_end_matches('/').replace("github.com", "raw.githubusercontent.com"));
        println!("[-] Error: Failed to parse plugins.json from the provided URL. Reason: {}", fetch_error(&full));
        return;
    }
    if !m.get_one::<String>("update").unwrap().is_empty() {
        let u = m.get_one::<String>("update").unwrap().clone();
        let _p = plugin_path();
        if !Path::new(&_p).exists() {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", _p);
        }
        println!("[-] Error: No existing plugin found with the given URL: {}", u);
        return;
    }
    if !m.get_one::<String>("remove").unwrap().is_empty() {
        let _p = plugin_path();
        if !Path::new(&_p).exists() {
            println!("Failed to open plugins.json file. PLUGIN_PATH: {}", _p);
        }
        return;
    }
    run(&m);
}

fn fetch_error(_url: &str) -> String {
    // No network access in the build/test environment; mimic the offline error.
    let e = std::net::TcpStream::connect("raw.githubusercontent.com:443");
    match e {
        Ok(_) => "error sending request for url (".to_string(),
        Err(err) => format!(
            "error sending request for url ({}): error trying to connect: {}",
            _url, err
        ),
    }
}

fn run(m: &clap::ArgMatches) {
    let start = Instant::now();
    let clean = m.get_flag("clean");
    let thorough = m.get_flag("thorough");
    let display = m.get_flag("display");
    let show_line = m.get_flag("line");
    let hide = m.get_flag("hide");
    let ignore = m.get_flag("ignore");
    let fname = m.get_one::<String>("file").unwrap().clone();
    let dir = m.get_one::<String>("directory").unwrap().clone();
    let output = m.get_one::<String>("output").unwrap().clone();
    let drop_re = if !m.get_one::<String>("drop").unwrap().is_empty() {
        Some(Regex::new(m.get_one::<String>("drop").unwrap()).unwrap())
    } else {
        None
    };
    let filter_re = if !m.get_one::<String>("filter").unwrap().is_empty() {
        Some(Regex::new(m.get_one::<String>("filter").unwrap()).unwrap())
    } else {
        None
    };

    let mut writer: Box<dyn Write> = if !output.is_empty() {
        match create_output(&output, &fname, ignore) {
            Ok(w) => Box::new(w),
            Err(_) => return,
        }
    } else {
        Box::new(std::io::stdout())
    };
    let is_csv = !output.is_empty();

    if is_csv {
        let mut header = String::from("content_type");
        if display {
            header.push_str(", file");
        }
        if show_line {
            header.push_str(", line");
        }
        header.push_str(", data");
        let _ = writeln!(writer, "{}", header);
    }

    if !dir.is_empty() {
        let mut files = Vec::new();
        collect_files(Path::new(&dir), &mut files);
        for f in files {
            process_file(&f.to_string_lossy(), &fname, clean, thorough, display, show_line, hide, is_csv, &mut writer, &drop_re, &filter_re);
        }
    } else if !fname.is_empty() {
        process_file(&fname, &fname, clean, thorough, display, show_line, hide, is_csv, &mut writer, &drop_re, &filter_re);
    } else {
        if !m.get_flag("suppress") {
            println!("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)");
        }
        let stdin = std::io::stdin();
        let mut reader = BufReader::new(stdin.lock());
        process_reader(&mut reader, "", clean, thorough, display, show_line, hide, is_csv, &mut writer, &drop_re, &filter_re);
    }

    writer.flush().ok();
    if m.get_flag("time") {
        let e = start.elapsed();
        println!("[*] Time elapsed: {:02}h:{:02}m:{:02}s", e.as_secs() / 3600, (e.as_secs() % 3600) / 60, e.as_secs() % 60);
    }
}

fn create_output(output: &str, fname: &str, ignore: bool) -> Result<std::fs::File, ()> {
    match File::create(output) {
        Ok(f) => Ok(f),
        Err(e) => {
            if !ignore {
                if e.to_string().contains("No such file") {
                    println!("[-] Failed to open output file: {}", fname);
                } else {
                    println!("[-] Failed to open output file: {}. Error: {}", fname, e);
                }
            }
            Err(())
        }
    }
}

fn collect_files(dir: &Path, out: &mut Vec<std::path::PathBuf>) {
    if let Ok(rd) = std::fs::read_dir(dir) {
