// ---------------------------------------------------------------------------
// plugins.json handling
// ---------------------------------------------------------------------------
fn plugin_path() -> String {
    let home = std::env::var("HOME").unwrap_or_default();
    format!("{}/.DataSurgeon/plugins.json", home)
}

fn prompt_exit() -> bool {
    loop {
        println!("[+] Do you want to exit? (y/n): ");
        let mut buf = String::new();
        let _ = std::io::stdin().read_line(&mut buf);
        let t = buf.trim().to_lowercase();
        if t == "y" {
            return true;
        }
        if t == "n" {
            return false;
        }
        println!("[-] Invalid input. Please enter 'y' or 'n'.");
    }
}

fn plugin_parse_error() {
    println!("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.");
    if prompt_exit() {
        std::process::exit(1);
    }
}

/// Reads the plugin list. Prints the diagnostic message when the file is
/// missing and loops until the user confirms an exit when it is malformed.
fn load_plugins() -> () {
    loop {
        let p = plugin_path();
        let content = match std::fs::read_to_string(&p) {
            Ok(c) => c,
            Err(_) => {
                println!("Failed to open plugins.json file. PLUGIN_PATH: {}", p);
                return;
            }
        };
        match parse_plugins(&content) {
            Ok(()) => return,
            Err(()) => plugin_parse_error(),
        }
    }
}

fn parse_plugins(content: &str) -> Result<(), ()> {
    let v: serde_json::Value = match serde_json::from_str(content) {
        Ok(v) => v,
        Err(_) => return Err(()),
    };
    let items = match v.as_array() {
        Some(a) => a,
        None => return Err(()),
    };
    for it in items {
        let o = match it.as_object() {
            Some(o) => o,
            None => return Err(()),
        };
        if !o.contains_key("name")
            || !o.contains_key("description")
            || !o.contains_key("files")
            || !o.contains_key("repo")
        {
            return Err(());
        }
        if !o["name"].is_string() || !o["description"].is_string() {
            return Err(());
        }
        if !o["files"].is_array() {
            return Err(());
        }
    }
    Ok(())
}

